import { useCallback, useEffect, useRef, useState, useMemo } from 'react'
import { TextInput, useWindowDimensions, View } from 'react-native'
import Animated, {
	Extrapolation,
	interpolate,
	interpolateColor,
	type ScrollEvent,
	useAnimatedScrollHandler,
	useAnimatedStyle,
	useSharedValue,
	withTiming,
	runOnJS,
	withSpring
} from 'react-native-reanimated'
import { StatusBar } from 'expo-status-bar'
import { SafeAreaView } from 'react-native-safe-area-context'
import { View as MotiView } from 'moti'
import {
	Badge,
	ShineEffect,
	SearchBarOverlay,
	SearchBarContainer
} from '@/components'
import {
	APPEAR_DURATION,
	BACKGROUND_TRANSITION_DURATION,
	SEARCH_BAR_HEIGHT
} from '@/constants'
import { ProjectGroupList } from './components/ProjectGroupList'
import {
	OrderByDirection,
	ProjectGroupOrderBy,
	OrganizationPlan,
	useGetProjectGroupsQuery
} from '@/generated/graphql'
import { colors, Theme, useTheme } from '@/theme'
import { useMe } from '@/utils/hooks/useMe'
import { useGetOrganizations } from '@/utils/hooks/useGetOrganizations'
import { Redirect, useFocusEffect } from 'expo-router'
import { defineStyles } from '@/utils/defineStyles'
import { OrganizationProfileImage } from './components/OrganizationProfileImage'
import { useOrganizationStore } from '@/stores/organizationStore'
import { EmptyStateContainer } from './components/EmptyStateContainer'
import {
	HomeScreenFilter,
	useHomeScreenFilterStore,
	homeScreenFilterConfigs
} from './state/filters'
import { Image } from 'expo-image'
import { capitalize } from 'lodash'
import { upgradePlanEmitter, UpgradePlanEvents } from '@/utils/emitter'
import { isPaidPlan } from '../profile/utils/organization'
import { prePromptStoreRating } from '@/utils/pre-prompt-store-rating'

type Organization = {
	id: string
	name: string
	logoUrl: string | null
	plan: OrganizationPlan
	canUseMax: boolean
}

export const HomeScreen = () => {
	const { me, loading: meLoading } = useMe()
	const { organizations } = useGetOrganizations()
	const filterStore = useHomeScreenFilterStore()
	const { hasFilter } = filterStore
	const { width, height } = useWindowDimensions()

	const { currentOrganizationIndex, setCurrentOrganizationIndex } =
		useOrganizationStore()
	const orgCount = organizations?.edges.length ?? 0

	const getWrappedIndex = (offset: number) => {
		if (orgCount === 0) return 0
		if (orgCount === 1) return 0
		if (orgCount === 2) return 1 - currentOrganizationIndex
		return (currentOrganizationIndex + offset + orgCount) % orgCount
	}

	const currentOrganization: Organization | undefined =
		organizations?.edges[currentOrganizationIndex]?.node
	const nextOrganization: Organization | undefined =
		organizations?.edges[getWrappedIndex(1)]?.node
	const prevOrganization: Organization | undefined =
		organizations?.edges[getWrappedIndex(-1)]?.node

	const [searchValue, setSearchValue] = useState('')
	const organizationId = currentOrganization?.id

	const { data, loading, fetchMore, previousData, refetch } =
		useGetProjectGroupsQuery({
			pollInterval: 60_000,
			variables: {
				organizationId: organizationId!,
				input: {
					organizationId: organizationId!,
					query: searchValue || null,
					orderBy: {
						field: ProjectGroupOrderBy.UPDATED_AT,
						direction: OrderByDirection.DESC
					}
				}
			},
			skip: !organizationId,
			onError: () => {
				// @TODO: handle error
			}
		})

	const { theme, isDark } = useTheme()

	useFocusEffect(
		useCallback(() => {
			if (organizationId) {
				refetch()
			}
		}, [organizationId, refetch])
	)

	const backgroundAnimation = useSharedValue(0)
	const scrollY = useSharedValue(0)
	const listYPosition = useSharedValue(height)

	const profileImageTranslateY = useSharedValue(0)
	const nextImageScale = useSharedValue(0)
	const prevImageScale = useSharedValue(0)
	const isAnimating = useSharedValue(false)

	useEffect(() => {
		profileImageTranslateY.set(0)
		nextImageScale.set(0)
		prevImageScale.set(0)
		isAnimating.set(false)
	}, [
		isAnimating,
		profileImageTranslateY,
		nextImageScale,
		prevImageScale,
		currentOrganizationIndex
	])

	const searchInputRef = useRef<TextInput>(null)
	const [isShining, setIsShining] = useState(true)
	const [isSearchBarOpen, setIsSearchBarOpen] = useState(false)
	const [isLoadingMore, setIsLoadingMore] = useState(false)

	const isSearchBarOpenShared = useSharedValue(false)

	useEffect(() => {
		const hasCachedData = Boolean(
			data?.projectGroups?.edges?.length ||
				previousData?.projectGroups?.edges?.length
		)
		if (hasCachedData && !meLoading) {
			setIsShining(false)
			backgroundAnimation.value = withTiming(1, {
				duration: BACKGROUND_TRANSITION_DURATION
			})
			listYPosition.value = withSpring(0, {
				duration: APPEAR_DURATION,
				dampingRatio: 1.25
			})
		}
	}, [data, previousData, meLoading])

	const setSearchBarOpenWithSharedValue = (value: boolean) => {
		setIsSearchBarOpen(value)
		isSearchBarOpenShared.value = value
	}

	const groups = loading ? previousData?.projectGroups : data?.projectGroups

	const projectGroups = useMemo(() => {
		if (!groups?.edges) return undefined
		const seen = new Set<string>()
		return groups.edges.reduce<typeof groups.edges[number]['node'][]>(
			(acc, edge) => {
				if (!seen.has(edge.node.id)) {
					seen.add(edge.node.id)
					acc.push(edge.node)
				}
				return acc
			},
			[]
		)
	}, [groups?.edges])
	const filteredProjectGroups = projectGroups?.filter((group) => {
		let condition = true
		if (
			hasFilter(HomeScreenFilter.DRAFT) &&
			!hasFilter(HomeScreenFilter.PUBLISHED)
		) {
			condition = condition && group.slug === null
		}
		if (
			hasFilter(HomeScreenFilter.PUBLISHED) &&
			!hasFilter(HomeScreenFilter.DRAFT)
		) {
			condition = condition && group.slug !== null
		}
		if (
			hasFilter(HomeScreenFilter.WEB) &&
			!hasFilter(HomeScreenFilter.MOBILE)
		) {
			condition = condition && group.lastRevisionWithExpoBundle === null
		}
		if (
			hasFilter(HomeScreenFilter.MOBILE) &&
			!hasFilter(HomeScreenFilter.WEB)
		) {
			condition = condition && group.lastRevisionWithExpoBundle !== null
		}
		return condition
	})
	const isEmpty = filteredProjectGroups?.length === 0
	const handleFetchMoreProjects = async () => {
		setIsLoadingMore(true)

		const organizationId = currentOrganization?.id ?? ''
		const after = data?.projectGroups?.pageInfo?.endCursor

		try {
			await fetchMore({
				variables: {
					organizationId,
					after
				}
			})
			setIsLoadingMore(false)
		} catch (error) {
			console.error(error)
			setIsLoadingMore(false)
		}
	}

	const onAnimationComplete = () => {
		backgroundAnimation.set(
			withTiming(1, {
				duration: BACKGROUND_TRANSITION_DURATION
			})
		)
		listYPosition.set(
			withSpring(0, {
				duration: APPEAR_DURATION,
				dampingRatio: 1.25
			})
		)
		runOnJS(setIsShining)(false)
	}

	const onScroll = useAnimatedScrollHandler({
		onScroll: (event: ScrollEvent) => {
			scrollY.set(event.contentOffset.y)
		}
	})

	const handleBadgePress = useCallback(() => {
		if (!currentOrganization?.plan.toLowerCase().startsWith('free')) {
			return
		}

		upgradePlanEmitter.emit(UpgradePlanEvents.OPEN_MODAL)
	}, [currentOrganization])

	const backgroundFadeStyle = useAnimatedStyle(() => {
		const backgroundColor = isDark
			? colors[theme].gray[100]
			: colors[theme].gray[75]
		return {
			backgroundColor: interpolateColor(
				backgroundAnimation.get(),
				[0, 1],
				[`${backgroundColor}ff`, `${backgroundColor}00`]
			)
		}
	})

	const searchBarBackgroundFadeStyle = useAnimatedStyle(() => {
		const backgroundColor = isDark
			? colors[theme].gray[75]
			: colors[theme].gray[50]
		return {
			backgroundColor: interpolateColor(
				backgroundAnimation.get(),
				[0, 1],
				[`${backgroundColor}ff`, `${backgroundColor}00`]
			)
		}
	})

	const searchBarFadeStyle = useAnimatedStyle(() => {
		if (isSearchBarOpenShared.value) {
			return {
				opacity: 0,
				transform: [{ translateY: 0 }]
			}
		}
		const opacity = interpolate(
			scrollY.value,
			[0, 30],
			[1, 0],
			Extrapolation.CLAMP
		)
		const translateY = interpolate(
			scrollY.value,
			[0, 30],
			[0, -30],
			Extrapolation.CLAMP
		)
		return {
			opacity: opacity,
			transform: [{ translateY }]
		}
	})

	const scrollScaleDownStyle = useAnimatedStyle(() => ({
		transform: [
			{
				scale: interpolate(
					scrollY.get(),
					[0, 100],
					[1, 0.8],
					Extrapolation.CLAMP
				)
			}
		]
	}))

	useEffect(() => {
		const promptRating = async () => {
			try {
				await prePromptStoreRating()
			} catch (error) {
				console.warn('Failed to prompt rating:', error)
			}
		}
		promptRating()
	}, [])

	if (!meLoading && !me) {
		return <Redirect href="/sign-up" />
	}

	return (
		<>
			<StatusBar style={isDark ? 'light' : 'dark'} />
			{isShining ? (
				<ShineEffect
					shineCondition={loading || meLoading}
					shineWidth={width}
					onAnimationComplete={onAnimationComplete}
				/>
			) : (
				// responsible for blurred search bar
				<SearchBarOverlay
					isSearchBarOpen={isSearchBarOpen}
					setIsSearchBarOpen={setSearchBarOpenWithSharedValue}
					searchInputRef={searchInputRef}
					searchValue={searchValue}
					setSearchValue={setSearchValue}
					placeholder="Search in projects"
				/>
			)}
			<SafeAreaView style={styles.safeArea(theme)} edges={['top']}>
				<View style={styles.headerContainer}>
					<Animated.View style={[styles.headerLeft, backgroundFadeStyle]}>
						<MotiView
							from={{ opacity: 0 }}
							animate={{ opacity: isShining ? 0 : 1 }}
							transition={{
								type: 'timing',
								duration: APPEAR_DURATION
							}}
							style={[scrollScaleDownStyle, styles.headerLeftContainer]}
						>
							<Image
								source={{ uri: 'anything-text-logo' }}
								style={{
									height: 28,
									width: 108,
									tintColor: colors[theme].gray[900]
								}}
								contentFit="contain"
							/>
							<Badge
								color="purple"
								onPress={handleBadgePress}
								disabled={isPaidPlan(
									currentOrganization?.plan ?? OrganizationPlan.FREE_USAGE
								)}
							>
								{currentOrganization?.plan.toLowerCase().startsWith('pro') &&
								currentOrganization?.canUseMax
									? 'Max'
									: capitalize(currentOrganization?.plan.split('_')[0])}
							</Badge>
						</MotiView>
					</Animated.View>
					{currentOrganization && nextOrganization && prevOrganization && (
						<OrganizationProfileImage
							currentOrganization={currentOrganization}
							nextOrganization={nextOrganization}
							prevOrganization={prevOrganization}
							currentOrganizationIndex={currentOrganizationIndex}
							getWrappedIndex={getWrappedIndex}
							setCurrentOrganizationIndex={setCurrentOrganizationIndex}
							isShining={isShining}
							backgroundAnimation={backgroundAnimation}
							hasOnlyOneOrganization={orgCount === 1}
						/>
					)}
				</View>

				<MotiView
					from={{ height: SEARCH_BAR_HEIGHT }}
					animate={{
						height: isSearchBarOpen ? 0 : SEARCH_BAR_HEIGHT,
						marginVertical: isSearchBarOpen ? -12 : 0
					}}
					transition={{
						type: 'timing',
						duration: 250
					}}
					style={[
						styles.searchBarButtonContainer,
						searchBarFadeStyle,
						searchBarBackgroundFadeStyle
					]}
				>
					{/* responsible for home screen search bar */}
					<MotiView
						from={{ opacity: 0 }}
						animate={{ opacity: isShining ? 0 : 1 }}
						transition={{
							type: 'timing',
							duration: APPEAR_DURATION
						}}
					>
						<SearchBarContainer
							searchInputRef={searchInputRef}
							setIsSearchBarOpen={setSearchBarOpenWithSharedValue}
							searchValue={searchValue}
							setSearchValue={setSearchValue}
							placeholder="Search in projects"
							filterConfigs={homeScreenFilterConfigs}
							filterStore={filterStore}
						/>
					</MotiView>
				</MotiView>

				{!isEmpty && filteredProjectGroups && (
					<ProjectGroupList
						projectGroups={filteredProjectGroups}
						hasMore={groups?.pageInfo.hasNextPage ?? false}
						isRefreshing={isShining}
						isLoadingMore={isLoadingMore}
						onFetchMoreProjects={handleFetchMoreProjects}
						onScroll={onScroll}
						onRefresh={refetch}
						listYPosition={listYPosition}
						parentScrollY={scrollY}
						isShining={isShining}
						isSearchBarOpen={isSearchBarOpen}
					/>
				)}

				<EmptyStateContainer
					isShining={isShining}
					isEmpty={isEmpty}
					isRefreshing={isLoadingMore}
					onRefresh={refetch}
					text="Start building something real."
				/>
			</SafeAreaView>
		</>
	)
}

const styles = defineStyles({
	safeArea: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].background,
		paddingTop: 20,
		gap: 20
	}),
	headerContainer: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		zIndex: 10,
		paddingHorizontal: 20
	},
	headerLeftContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 10
	},
	headerLeft: {
		borderRadius: 8
	},
	headerRight: {
		width: 44,
		height: 44,
		borderRadius: 50,
		justifyContent: 'center',
		alignItems: 'center',
		overflow: 'hidden'
	},
	headerRightOrganizationContainer: {
		width: '100%',
		height: '100%',
		justifyContent: 'center',
		alignItems: 'center'
	},
	headerRightProfileButton: {
		borderRadius: 50,
		justifyContent: 'center',
		alignItems: 'center'
	},
	headerRightAnimatedContainer: {
		justifyContent: 'center',
		alignItems: 'center'
	},
	headerRightMotiContainer: {
		justifyContent: 'center',
		alignItems: 'center',
		width: '75%',
		height: '75%'
	},
	headerRightAppearingContainer: {
		position: 'absolute',
		width: '75%',
		height: '75%'
	},
	headerRightImage: {
		width: '100%',
		height: '100%',
		borderRadius: 50
	},
	horizontalContainer: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		zIndex: 4
	},
	searchBarButtonAnimatedContainer: {
		zIndex: 4
	},
	searchBarButtonContainer: {
		borderRadius: 28,
		zIndex: 4,
		marginHorizontal: 20
	}
})
